        emon.Testport.AssertEq(emon.Port.SrcU8(s, 0), 48, "first byte");
        emon.Testport.AssertEq(emon.Port.SrcU8(s, 9), 57, "last byte");
        emon.Testport.AssertEq(emon.Port.BlobLen(emon.Port.SrcSlice(s, 2, 5)), 3, "a span's length");
        emon.Testport.AssertEq(emon.Port.BlobU8(emon.Port.SrcSlice(s, 2, 5), 0), 50, "a span's first byte");
        emon.Testport.AssertEq(emon.Port.BlobU8(emon.Port.SrcSlice(s, 2, 5), 2), 52, "a span's last byte");
        emon.Testport.AssertEq(emon.Port.BlobLen(emon.Port.SrcSlice(s, 4, 4)), 0, "an empty span");
        emon.Testport.AssertEq(emon.Port.BlobLen(emon.Port.SrcSlice(s, 0, 10)), 10, "the whole source");
        emon.Port.SrcHint(s, 0, 5);
        emon.Testport.AssertEq(emon.Port.SrcU8(s, 3), 51, "a hint changes nothing");
        emon.Testport.AssertEq(StM(s), 0, "an in-memory source never misses");
    }
