    [Xunit.Fact]
    public static void TestAReadInAMissingChunkAnswersZeroAndSetsTheFlag() {
        emon.Port.Src @base = emon.Testport.SrcChunked(emon.Testport.TextBlob("0123456789abcdef"), 4, 0);
        emon.Port.Src v = emon.Testport.SrcView(@base);
        emon.Testport.AssertEq(emon.Port.SrcLen(v), 16, "the length is known before any byte is");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 8, 0), 4, "four chunks");
        emon.Testport.AssertEq(StM(v), 0, "no miss yet");
        emon.Testport.AssertEq(emon.Port.SrcU8(v, 5), 0, "a miss answers 0");
        emon.Testport.AssertEq(StM(v), 1, "and sets the flag");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 4, 0), 1, "one chunk is pending");
        emon.Testport.AssertEq(emon.Port.SrcU8(v, 6), 0, "the same chunk again");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 4, 0), 1, "a chunk is recorded once");
        emon.Testport.AssertEq(emon.Port.SrcU8(v, 0), 0, "another chunk");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 4, 0), 2, "two pending");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 0, 0), 2, "a fetch makes the pending chunks resident");
        emon.Testport.AssertEq(emon.Testport.SrcCtl(@base, 4, 0), 0, "and nothing is pending");
        emon.Testport.AssertEq(StM(v), 1, "the view that missed stays missed");
        emon.Testport.AssertEq(emon.Port.SrcU8(v, 5), 53, "the cache grew: the byte is there now");
        emon.Port.Src w = emon.Testport.SrcView(@base);
        emon.Testport.AssertEq(StM(w), 0, "a fresh view starts clean");
        emon.Testport.AssertEq(emon.Port.SrcU8(w, 5), 53, "it reads the resident byte");
        emon.Testport.AssertEq(emon.Port.SrcU8(w, 0), 48, "both resident chunks");
        emon.Testport.AssertEq(StM(w), 0, "without a miss");
        emon.Testport.AssertEq(emon.Port.SrcU8(w, 9), 0, "a chunk still missing");
        emon.Testport.AssertEq(StM(w), 1, "misses again");
        emon.Testport.AssertEq(StM(v), 1, "and the views are independent");
    }
